import { LATEST_SCHEMA_MIGRATION } from './backup/inventory.js'

/**
 * Independent new-project root provenance. This is an OFFLINE review of
 * provider records, not an attestation generated by the deployed app.
 * A trusted operator must supply the evidence directly from Neon API/SQL;
 * never accept evidence fields from Vercel env, a browser or a request body.
 * Nothing here enables runtime access to private health data.
 */
export const REQUIRED_EMPTY_OWNER_TABLES = [
  'health_profile', 'body_metrics', 'nutrition_entries', 'workout_sessions',
  'goals', 'supplements', 'daily_context', 'hydration_events', 'bowel_events',
  'benchmark_results', 'coach_tasks', 'ai_usage', 'primary_goal_intent_events',
] as const

export type PiqIndependentRootEvidence = {
  project: {
    source: 'neon_api'
    id: string
    createdAt: string
  }
  branch: {
    source: 'neon_api'
    projectId: string
    id: string
    createdAt: string
    parentId: null
    isDefault: boolean
  }
  initialSql: {
    source: 'neon_sql'
    projectId: string
    branchId: string
    publicTableCount: number
    authUserCount: number
    authSessionCount: number
  }
  migratedSql: {
    source: 'neon_sql'
    projectId: string
    branchId: string
    migrationCount: number
    migrationSequenceValid: boolean
    lastMigration: string
    ownerTableCounts: Record<(typeof REQUIRED_EMPTY_OWNER_TABLES)[number], number>
    authUserCount: number
    authSessionCount: number
  }
  auth: {
    source: 'neon_auth_api'
    projectId: string
    branchId: string
    provider: 'better_auth'
    qaAuthProjectId: string
    productionAuthProjectId: string
  }
}

export function independentlyVerifiedEmptyRoot(input: {
  expectedProjectId: string
  expectedBranchId: string
  productionProjectId: string
  branch: {
    projectId: string
    branchId: string
    parentId: string | null
    initSource: string
  }
  proof: PiqIndependentRootEvidence | null | undefined
}): boolean {
  const { expectedProjectId: projectId, expectedBranchId: branchId,
    productionProjectId, branch, proof } = input
  if (!proof || !projectId || !branchId || !productionProjectId ||
      projectId === productionProjectId ||
      branch.projectId !== projectId || branch.branchId !== branchId ||
      branch.parentId !== null || branch.initSource !== 'parent-data') return false

  const { project, branch: root, initialSql, migratedSql, auth } = proof
  if (project.source !== 'neon_api' || project.id !== projectId ||
      root.source !== 'neon_api' || root.id !== branchId ||
      root.projectId !== projectId || root.parentId !== null ||
      root.isDefault !== true ||
      initialSql.source !== 'neon_sql' || migratedSql.source !== 'neon_sql' ||
      auth.source !== 'neon_auth_api' ||
      initialSql.projectId !== projectId || migratedSql.projectId !== projectId ||
      auth.projectId !== projectId ||
      initialSql.branchId !== branchId || migratedSql.branchId !== branchId ||
      auth.branchId !== branchId || auth.provider !== 'better_auth' ||
      !auth.qaAuthProjectId || !auth.productionAuthProjectId ||
      auth.qaAuthProjectId === auth.productionAuthProjectId) return false

  // A newly created project/root are born together, not months apart.
  const projectAt = Date.parse(project.createdAt)
  const rootAt = Date.parse(root.createdAt)
  if (!Number.isFinite(projectAt) || !Number.isFinite(rootAt) ||
      Math.abs(projectAt - rootAt) > 60_000) return false

  if (initialSql.publicTableCount !== 0 ||
      initialSql.authUserCount !== 0 || initialSql.authSessionCount !== 0 ||
      migratedSql.authUserCount !== 0 || migratedSql.authSessionCount !== 0 ||
      migratedSql.migrationSequenceValid !== true ||
      migratedSql.migrationCount !== Number(LATEST_SCHEMA_MIGRATION.slice(0, 4)) ||
      migratedSql.lastMigration !== LATEST_SCHEMA_MIGRATION) return false

  return REQUIRED_EMPTY_OWNER_TABLES.every((name) =>
    migratedSql.ownerTableCounts?.[name] === 0)
}
